        if cc.get(&n).unwrap() == 3 || cc.get(&n).unwrap() == 2 {
            m = std::cmp::max(m, cc.get(&n).unwrap() * n);
        }
    }

    writeln!(io::stdout(), "{}", s - m).unwrap();
}
