use std::io::{self, Write};
use std::collections::HashMap;

fn main() {
    let mut n = String::new();
    io::stdin().read_line(&mut n).unwrap();
    let n: i32 = n.trim().parse().unwrap();
    let mut arr: HashMap<i32, i32> = HashMap::new();
    for _ in 0..n {
        let mut a = String::new();
        io::stdin().read_line(&mut a).unwrap();
        let a: i32 = a.trim().parse().unwrap();
        *arr.entry(a).or_insert(0) += 1;
    }
    // 
    let max1 = *arr.get(&1).unwrap_or(&0);
    let max2 = *arr.get(&2).unwrap_or(&0);
    let max3 = *arr.get(&3).unwrap_or(&0);
    let max4 = max(max1, max2);
    let max5 = max(max4, max3);
    writeln!(io::stdout(), "{}", n - max5).unwrap();
}
