use std::io::{self, Write};
use std::collections::HashMap;

fn main() {
    let mut n = String::new();
    io::stdin().read_line(&mut n).unwrap();
    let n: usize = n.trim().parse().unwrap();

    let mut id = HashMap::new();
    let mut tag = HashMap::new();
    let mut cnt = 0;
    let mut sk = Vec::new();
    let mut top = 0;

    for i in 1..=(2 * n) {
        let mut s = String::new();
        io::stdin().read_line(&mut s).unwrap();
        let s: Vec<_> = s.trim().split_whitespace().collect();

        if s[0] == "+" {
            sk.push(cnt);
            top += 1;
        } else {
            let x = s[0].parse::<usize>().unwrap();
            if !sk.len() || tag.get(&sk[top - 1]).unwrap() > &x {
                println!("NO");
                return;
            }
            id[sk[top - 1]] = x;
            if sk.len() > 1 {
                tag.insert(sk[top - 1], *tag.get(&sk[top - 1]).unwrap().clone() + x);
            }
        }
    }

    println!("YES");
    for i in 1..=n {
        println!("{}", id[i]);
    }

    println!("This is an unclosed string: ");
}
