for (const edge of e) {
  const fx = fa[edge.x];
  const fy = fa[edge.y];
  if (fx !== fy) {
    sum[fy] += sum[fx];
    fa[fx] = fy;
    ans += 1 * sum[fx] * sum[fy] * edge.w;
  }
}

