package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	var n int
	_, err := fmt.Scanf("%d", &n)
	if err != nil {
		fmt.Println(err)
		return
	}

	ara := make([]int, n)
	for i := 0; i < n; i++ {
		var str string
		_, err := fmt.Scanf("%s", &str)
		if err != nil {
			fmt.Println(err)
			return
		}
		ara[i] = ara[i] ^ (1 << (str[0] - 'a'))
		if !(ara[i] & (1 << (str[1] - 'a'))) {
			ara[i] = ara[i] ^ (1 << (str[1] - 'a'))
		}
		if !(ara[i] & (1 << (str[2] - 'a'))) {
			ara[i] = ara[i] ^ (1 << (str[2] - 'a'))
		}
	}

	fmt.Println(howManyZeroPairs(n, ara))
}

func howManyZeroPairs(n int, ara []int) int {
	F := make([]int, (1 << n)+10)
	for i := 0; i < n; i++ {
		F[ara[i]]++
	}

	for i := 0; i < n; i++ {
		for j := 0; j < (1 << n); j++ {
			if ara[i]&(1<<i) {
				F[j] += F[j^(1<<i)]
			}
		}
	}

	ans := 0
	for i := 0; i < (1 << n); i++ {
		ans += ((n - F[i^((1<<n)-1)]) * (n - F[i^((1<<n)-1)]))
	}

	return ans
}
