import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

        int n = Integer.parseInt(br.readLine());
        int ara[] = new int[n];

        for (int i = 0; i < n; i++) {
            String str = br.readLine();
            ara[i] = ara[i] ^ (1 << (str.charAt(0) - 'a'));
            if (!(ara[i] & (1 << (str.charAt(1) - 'a'))))
                ara[i] = ara[i] ^ (1 << (str.charAt(1) - 'a'));
            if (!(ara[i] & (1 << (str.charAt(2) - 'a'))))
                ara[i] = ara[i] ^ (1 << (str.charAt(2) - 'a'));
        }

        bw.write(howManyZeroPairs(n, ara) + "
");
        bw.close();
    }

    public static int howManyZeroPairs(int n, int ara[]) {
        int F[] = new int[(1 << n) + 10];
        for (int i = 0; i < n; i++) {
            F[ara[i]]++;
        }

        for (int i = 0; i < n; i++) {
            for (int mask = 0; mask < (1 << n); mask++) {
                if ((ara[i] & (1 << i)) != 0) {
                    F[mask] += F[mask ^ (1 << i)];
                }
            }
        }

        int ans = 0;
        for (int i = 0; i < (1 << n); i++) {
            ans += ((n - F[i ^ ((1 << n) - 1)]) * (n - F[i ^ ((1 << n) - 1)]));
        }

        return ans;
    }
}
