use std::io::{self, Write};
use std::str::FromStr;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines: Vec<String> = input.split('\n').map(|s| s.to_string()).collect();

    let n: usize = lines[0].parse().unwrap();
    let ara: Vec<usize> = (0..n).map(|_| 0).collect();

    for i in 0..n {
        let str: String = lines[i + 1].clone();
        ara[i] = ara[i] ^ (1 << (str.chars().next().unwrap() as u8 - 'a'));
        if !(ara[i] & (1 << (str.chars().nth(1).unwrap() as u8 - 'a'))) {
            ara[i] = ara[i] ^ (1 << (str.chars().nth(1).unwrap() as u8 - 'a'));
        }
        if !(ara[i] & (1 << (str.chars().nth(2).unwrap() as u8 - 'a'))) {
            ara[i] = ara[i] ^ (1 << (str.chars().nth(2).unwrap() as u8 - 'a'));
        }
    }

    println!("{}", howManyZeroPairs(n, ara));
}

fn howManyZeroPairs(n: usize, ara: Vec<usize>) -> usize {
    let mut F: Vec<usize> = vec![0; (1 << n) + 10];
    for i in 0..n {
        F[ara[i]] += 1;
    }

    let mut ans: usize = 0;
    for i in 0..(1 << n) {
        ans += ((n - F[i ^ ((1 << n) - 1)]) * (n - F[i ^ ((1 << n) - 1)]));
    }

    ans
}
