        for (int i = 0; i < n; i++) {
            String str = br.readLine();
            ara[i] = ara[i] ^ (1 << (str.charAt(0) - 'a'));
            if (!(ara[i] & (1 << (str.charAt(1) - 'a'))))
                ara[i] = ara[i] ^ (1 << (str.charAt(1) - 'a'));
            if (!(ara[i] & (1 << (str.charAt(2) - 'a'))))
                ara[i] = ara[i] ^ (1 << (str.charAt(2) - 'a'));
        }

        bw.write(howManyZeroPairs(n, ara) + "
