    public static int howManyZeroPairs(int n, int ara[]) {
        int F[] = new int[(1 << n) + 10];
        for (int i = 0; i < n; i++) {
            F[ara[i]]++;
        }

        for (int i = 0; i < n; i++) {
            for (int mask = 0; mask < (1 << n); mask++) {
                if ((ara[i] & (1 << i)) != 0) {
                    F[mask] += F[mask ^ (1 << i)];
                }
            }
        }

        int ans = 0;
        for (int i = 0; i < (1 << n); i++) {
            ans += ((n - F[i ^ ((1 << n) - 1)]) * (n - F[i ^ ((1 << n) - 1)]));
        }

        return ans;
    }
