import math

s1 = input()
s2 = input()
c1 = 0 
c2 = 0
c3 = 0

for items in s1:
    if items == "+":
        c1 += 1 
    if items == "-":
        c2 += 1 

for items in s2:
    if items == "+":
        c1 -= 1 
    if items == "-":
        c2 -= 1
    if items == "?":
        c3 += 1

# Corrected variable name
x = math.factorial(c1 + c2) // (math.factorial(c1) * math.factorial(c2))  # Corrected variable name

if (c2 < 0):
    print(0.000)
elif (c2 > c3):
    print(0.000)
else:
    print(x / (2**(c1 + c2)))


# Test case
