    for i in range(x, -1, -1):
        if d[i] < 0 or vis[d[i]]:
            if len(seq) <= h:
                pass
            else:
                cnt += 1
                # Corrected indexing error
                if cnt == a[seq[cnt - 1]]:  # Changed seq[h] to seq[cnt - 1]
                    h += 1
                    cnt = 0
        else:
